package android.app;
import android.content.Context; import android.content.Intent; import java.util.*;
public class PendingIntent { public static final int FLAG_NO_CREATE=1, FLAG_IMMUTABLE=2, FLAG_UPDATE_CURRENT=4; public static final List<String> made=new ArrayList<>(); private final String desc; private PendingIntent(String d){desc=d;} public static PendingIntent getBroadcast(Context c,int id,Intent i,int flags){String head=i.getAction()!=null?i.getAction():(i.getTargetClass()!=null?i.getTargetClass().getName():"null"); String tail=i.getStringExtra("uid"); if(tail==null && i.getData()!=null && i.getData().toString().startsWith("todo://done/")) tail=i.getData().toString().substring("todo://done/".length()); String s="broadcast#"+id+":"+head+(tail!=null?":"+tail:""); made.add(s); return new PendingIntent(s);} public static PendingIntent getActivity(Context c,int id,Intent i,int flags){String s="activity#"+id+":"+(i.getStringExtra("widget_action")!=null?i.getStringExtra("widget_action"):i.getAction()); made.add(s);return new PendingIntent(s);} public void cancel(){} public String describe(){return desc;} }
